const aiResponse = $input.first().json.output;

let jsonString = aiResponse.trim();
if (jsonString.startsWith('```json')) {
  jsonString = jsonString.replace(/```json\n?/g, '').replace(/```/g, '').trim();
} else if (jsonString.startsWith('```')) {
  jsonString = jsonString.replace(/```\n?/g, '').trim();
}

let extractedData;
try {
  extractedData = JSON.parse(jsonString);
} catch (error) {
  const jsonMatch = jsonString.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    extractedData = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Nu s-a putut extrage JSON: ' + jsonString);
  }
}

const sanitize = (str) => {
  if (!str || str === 'NECUNOSCUT') return 'NECUNOSCUT';
  return str.trim().replace(/[/\\:*?"<>|]/g, '').replace(/\s+/g, '_').replace(/_{2,}/g, '_').toUpperCase();
};

const numeCompanie = sanitize(extractedData.nume_companie);
const numeNava = sanitize(extractedData.nume_nava);
const numarProiect = sanitize(extractedData.numar_proiect);

if (numeCompanie === 'NECUNOSCUT' && numeNava === 'NECUNOSCUT' && numarProiect === 'NECUNOSCUT') {
  throw new Error('AI nu a putut extrage nicio informație validă!');
}

const gmail = $('Gmail Trigger - Survey').first().json;

return [{
  json: {
    nume_companie: numeCompanie,
    nume_nava: numeNava,
    numar_proiect: numarProiect,
    emailId: gmail.id,
    emailSubject: gmail.Subject,
    emailFrom: gmail.From
  }
}];

// Ia toate item-urile de input
const items = $input.all();

return items.map(item => {
  const filename = item.json.name || item.json.filename || item.json.fileName || 'attachment';

  return {
    json: {
      ...item.json,
      filename: filename
    },
    binary: item.binary
  };
});

const allInputs = $input.all();
const companieFolderId = allInputs[0]?.json?.companieFolderId || allInputs[1]?.json?.companieFolderId;
const parseData = $('Parse și Validare Date').first().json;

return [{
  json: {
    ...parseData,
    companieFolderId: companieFolderId
  },
  pairedItem: 0
}];

const allInputs = $input.all();
const navaFolderId = allInputs[0]?.json?.navaFolderId || allInputs[1]?.json?.navaFolderId;
const mergeCompanieData = $('Merge Companie').first().json;

return [{
  json: {
    ...mergeCompanieData,
    navaFolderId: navaFolderId
  },
  pairedItem: 0
}];

const allInputs = $input.all();
const proiectFolderId = allInputs[0]?.json?.proiectFolderId || allInputs[1]?.json?.proiectFolderId;

return [{
  json: {
    proiectFolderId: proiectFolderId
  },
  pairedItem: 0
}];

const proiectFolderId = $input.first().json.proiectFolderId;
const attachmentItems = $('Edit Fields2').all();

return attachmentItems.map(item => {
  const binaryData = item.binary ? Object.values(item.binary)[0] : null;

  return {
    json: {
      ...item.json,
      proiectFolderId: proiectFolderId
    },
    binary: {
      data: binaryData
    }
  };
});

