// Definim ce date sunt obligatorii
const requiredFields = {
  'nume_nava': 'Numele navei',
  'numar_proiect': 'Numărul proiectului',
  'port': 'Portul',
  'data_survey': 'Data survey-ului',
  'client': 'Clientul'
};

const data = $input.all()[0].json;
const missingFields = [];

// Verificăm ce lipsește
for (const [field, label] of Object.entries(requiredFields)) {
  if (!data[field] || data[field] === '' || data[field] === 'N/A') {
    missingFields.push(label);
  }
}

// Returnăm rezultatul
return {
  json: {
    ...data,
    hasAllData: missingFields.length === 0,
    missingFields: missingFields,
    missingFieldsText: missingFields.join(', ')
  }
};

