const item = $json;

const missing = item.missingFields || [];

const text =
  `❗ Lipsesc următoarele informații:\n\n` +
  missing.map(f => `• ${f}`).join('\n') +
  `\n\nTe rog să le adaugi pe rând 👇`;

return [
  {
    json: {
      text,
      missingFields: missing
    }
  }
];

const fields = $json.missingFields;

const inline_keyboard = fields.map(field => ([
  {
    text: `➕ Adaugă ${field}`,
    callback_data: `ADD_FIELD::${field}`
  }
]));

return [
  {
    json: {
      text: $json.text,
      reply_markup: {
        inline_keyboard
      }
    }
  }
];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const parsed   = $('Parse Session Answers').first().json;
const answers  = parsed.session_answers || [];
const survey_type_idx = parsed.survey_type_idx || 1;

const TYPES = [
  "Pre-Discharge Cargo Condition Survey",
  "Loading Survey",
  "Condition Survey",
  "Damage Survey",
  "Bunker Survey"
];

const chat_id = $('Telegram — Bot Trigger').first().json?.message?.chat?.id
             || $('Telegram — Bot Trigger').first().json?.callback_query?.message?.chat?.id
             || 0;

const get = (i) => (answers[i] || '').trim();

const vessel_name    = get(0).toUpperCase();
const port           = get(1).toUpperCase();
const survey_date    = get(2);
const requested_by   = get(3);
const customer_ref   = get(4);
const bl_number      = get(5);
const shipper        = get(6);
const consignee      = get(7);
const cargo_desc     = get(8);
const packages_count = get(9);
const gross_weight   = get(10);
const berth_terminal = get(11);
const period         = get(12);
const surveyor_name  = get(13);
const imo_raw        = get(14).split(',').map(s => s.trim());

const survey_type = TYPES[survey_type_idx] || TYPES[1];

// Ref from Supabase RPC
const ref_result = $('Supabase — generate_ref').first().json;
const ref_arr    = Array.isArray(ref_result) ? ref_result : [ref_result];
const report_ref = ref_arr[0]?.ref_code || 'PL000_2026';
const ref_id     = ref_arr[0]?.ref_id   || null;

const year       = new Date().getFullYear();
const date_parts = period.split(/[-–]/).map(s => s.trim());

// Photos collected during photo wizard — read from packing_item_photos
// These are resolved as public_url after upload
const photos = $('Supabase — Read Photo URLs').first().json;
const photo_arr = Array.isArray(photos) ? photos : [photos];
const photo_urls = photo_arr.map(p => p.public_url || '').filter(Boolean);

const payload = {
  // Cover
  REPORT_REF:       report_ref,
  SURVEY_TYPE:      survey_type,
  VESSEL_NAME:      vessel_name,
  PORT:             port,
  COUNTRY:          'ROMANIA',
  DATE_FROM:        date_parts[0] || survey_date,
  DATE_TO:          date_parts[1] || survey_date,
  YEAR:             String(year),
  REQUESTED_BY:     requested_by,
  CUSTOMER_REF:     customer_ref,
  TOTAL_PAGES:      '~',

  // Certification
  BERTH_NO:         (berth_terminal.match(/\d+/) || [''])[0],
  TERMINAL_NAME:    berth_terminal.replace(/Berth\s*\d+[,\s]*/i,'').trim(),
  PORT_OF_LOADING:  port,
  LOADING_COUNTRY:  'ROMANIA',
  BL_NUMBER:        bl_number,
  BL_DATE:          survey_date,
  CARGO_DESCRIPTION: cargo_desc,
  PACKAGES_COUNT:   packages_count,
  TOTAL_WEIGHT_KG:  gross_weight,
  SHIPPER_NAME:     shipper,
  CONSIGNEE_NAME:   consignee,
  NOTIFY_PARTY:     consignee,

  // Companies
  PI_SURVEYOR:          'LeeWu Maritime Survey S.R.L.',
  STEVEDORING_CO:       'N/A',
  ATTENDING_SURVEYOR:   surveyor_name,
  OTHERS_ATTENDANCE:    'N/A',

  // Vessel
  VESSEL_NAME_PLAIN: vessel_name,
  IMO_NUMBER:        imo_raw[0] || 'N/A',
  CALL_SIGN:         'N/A',
  VESSEL_TYPE:       imo_raw[1] || 'General Cargo',
  FLAG:              imo_raw[2] || 'N/A',
  GROSS_TONNAGE:     'N/A',
  DEADWEIGHT:        'N/A',
  LOA:               'N/A',
  BREADTH:           'N/A',
  YEAR_BUILT:        'N/A',
  HOLDS_HATCHES:     'N/A',

  // Cargo detail
  CARGO_DESCRIPTION_DETAIL: cargo_desc,
  PACKING_DESCRIPTION:      'N/A',

  // Survey meta
  SURVEY_TYPE_PLAIN:  survey_type,
  WORKING_HOURS:      '07:00 – 19:00 hrs.',
  MEAL_BREAKS:        '12:00 – 13:00 hrs.',
  SHIFT_CHANGES:      'N/A',
  PHOTOGRAPHS_INDEX_PLACEHOLDER: photo_urls.length
    ? photo_urls.map((u,i) => `Photograph ${i+1}: ${u}`).join('\n')
    : 'No photographs attached.',
  EXECUTIVE_SUMMARY_TEXT: 'Survey conducted as per scope. Full details in body of report.',
  SURVEYOR_NAME:      surveyor_name,

  // Photos for replaceImage in Google Docs
  photo_urls,
  cover_photo_url_1:  photo_urls[0] || '',
  cover_photo_url_2:  photo_urls[1] || '',
  cover_photo_url_3:  photo_urls[2] || '',

  // Internal for folder logic
  report_ref, ref_id,
  nume_companie: requested_by.replace(/\s+/g,'_').toUpperCase(),
  nume_nava:     vessel_name,
  numar_proiect: report_ref,
  port, data_survey: survey_date, client: requested_by,
  survey_date, vessel_name, bl_number,
  client_name: requested_by, client_ref: customer_ref,
  chat_id,
  timestamp: new Date().toISOString()
};

return [{ json: payload }];

