const msg = $('Telegram — Bot Trigger').first().json.message;
const photos = msg.photo; // array of PhotoSize objects, last = largest
const largest = photos[photos.length - 1];
const chat_id = msg.chat.id;
const user_id = msg.from.id;

// Retrieve which section this photo belongs to — stored in ai_conversations
// as a 'system' role row with content = 'PHOTO_SECTION::cover_1'
// (set when user clicked the inline keyboard button)
const session_rows = $('Supabase — Read Photo Section').first().json;
const section_arr  = Array.isArray(session_rows) ? session_rows : [session_rows];
const section_row  = section_arr.find(r => r.content?.startsWith('PHOTO_SECTION::'));
const photo_section = section_row
  ? section_row.content.replace('PHOTO_SECTION::','')
  : 'report_unknown';

const section_labels = {
  cover_1:  'Cover Photo 1',
  cover_2:  'Cover Photo 2',
  cover_3:  'Cover Photo 3',
  report_1: 'Report Photo 1',
  report_2: 'Report Photo 2',
  report_3: 'Report Photo 3',
  report_4: 'Report Photo 4',
  report_5: 'Report Photo 5',
};

return [{
  json: {
    file_id:       largest.file_id,
    file_unique_id: largest.file_unique_id,
    width:         largest.width,
    height:        largest.height,
    photo_section,
    caption_label: section_labels[photo_section] || photo_section,
    chat_id,
    user_id,
    timestamp: new Date().toISOString()
  }
}];

const extracted = $('Extract Photo File ID').first().json;
const chat_id   = extracted.chat_id;
const user_id   = extracted.user_id;
const section   = extracted.photo_section;
const unique_id = extracted.file_unique_id;

// Build the storage path and public URL
const storage_path = `${chat_id}/${section}_${unique_id}.jpg`;
const public_url   = `${$vars.SUPABASE_URL}/storage/v1/object/public/survey-photos/${storage_path}`;

// Find survey_id from session (stored in ai_conversations system row)
const session = $('Supabase — Read Photo Section').first().json;
const sarr    = Array.isArray(session) ? session : [session];
const sid_row = sarr.find(r => r.content?.startsWith('SURVEY_ID::'));
const survey_id = sid_row ? sid_row.content.replace('SURVEY_ID::','') : null;

return [{
  json: {
    telegram_file_id: extracted.file_id,
    telegram_chat_id: chat_id,
    caption:          extracted.caption_label,
    uploaded_by:      user_id,
    storage_path,
    public_url,
    survey_id,
    item_code:        section,
    photo_section:    section
  }
}];

const chat_id = $('Extract Photo File ID').first().json.chat_id;
const section = $('Extract Photo File ID').first().json.caption_label;

// Count how many photos saved so far for this session
const saved = $('Supabase — Insert Photo Row').first().json;
const count_result = Array.isArray(saved) ? saved.length : 1;

return [{
  json: {
    chat_id,
    section,
    message: `✅ *${section}* salvată!\n\nTrimiți următoarea fotografie sau selectați altă secțiune.`
  }
}];

// Supabase returns a raw array of ai_conversations rows
// Each row.content is one wizard answer in order
const rows = $input.all();

// rows could be: [{json: {content:'TIAN QI'}}, {json:{content:'CONSTANTA'}}, ...]
// or if HTTP request returns single item with json=array: [{json: [{content:...}]}]
let answers = [];
let survey_type_idx = 1;

if (rows.length === 1 && Array.isArray(rows[0].json)) {
  // HTTP request returned array as single item
  const arr = rows[0].json;
  answers = arr.map(r => r.content || '');
  // First row might be the survey type callback stored as "TYPE::N"
} else {
  // splitOut already gave us individual rows
  answers = rows.map(r => {
    const c = r.json?.content || '';
    return c;
  });
}

// Extract survey_type_idx from session meta row (role=system)
// It's stored separately; if not found default to 1
const typeRow = answers.find(a => a.startsWith('TYPE::'));
if (typeRow) {
  survey_type_idx = parseInt(typeRow.replace('TYPE::','')) || 1;
  // Remove it from answers array
  answers = answers.filter(a => !a.startsWith('TYPE::'));
}

// Pad to 15 answers minimum
while (answers.length < 15) answers.push('');

return [{ json: { session_answers: answers, survey_type_idx } }];
